import Foundation
import SwiftUI

enum StudioEngine: String, CaseIterable, Identifiable, Codable {
    case standaloneCluster = "uncensored_horde"
    case homePCRTX = "local_gpu"
    case cloudFlux = "qwen21_turbo"

    var id: String { rawValue }

    var title: String {
        switch self {
        case .standaloneCluster:
            return "Standalone AI Cluster (24/7 Anywhere)"
        case .homePCRTX:
            return "Home PC RTX 2070 Super Bridge"
        case .cloudFlux:
            return "Instant Cloud Flux / Turbo"
        }
    }

    var shortTitle: String {
        switch self {
        case .standaloneCluster:
            return "AI Cluster"
        case .homePCRTX:
            return "RTX 2070S PC"
        case .cloudFlux:
            return "Cloud Flux"
        }
    }

    var subtitle: String {
        switch self {
        case .standaloneCluster:
            return "Generates directly on iPhone via Uncensored SDXL Cluster (WAI-Illustrious / Pony V6 / AlbedoBase). Works with PC off."
        case .homePCRTX:
            return "Renders on your home RTX 2070 Super GPU over Wi-Fi or Tailscale (308-token CLIP + Regional Duo Engine)."
        case .cloudFlux:
            return "Fast cloud synthesis directly on iPhone."
        }
    }

    var icon: String {
        switch self {
        case .standaloneCluster:
            return "sparkles.tv.fill"
        case .homePCRTX:
            return "desktopcomputer"
        case .cloudFlux:
            return "bolt.horizontal.circle.fill"
        }
    }
}

struct AspectRatioOption: Identifiable, Hashable {
    let id: String
    let label: String
    let subtitle: String
    let width: Int
    let height: Int

    static let all: [AspectRatioOption] = [
        AspectRatioOption(id: "832x1216", label: "832×1216", subtitle: "Full Body Portrait (SDXL Optimal)", width: 832, height: 1216),
        AspectRatioOption(id: "1024x1024", label: "1024×1024", subtitle: "Square 1:1 Masterpiece", width: 1024, height: 1024),
        AspectRatioOption(id: "1152x768", label: "1152×768", subtitle: "Duo Split / Wide 3:2", width: 1152, height: 768),
        AspectRatioOption(id: "1216x832", label: "1216×832", subtitle: "Cinematic Landscape", width: 1216, height: 832),
        AspectRatioOption(id: "768x1024", label: "768×1024", subtitle: "Fast Portrait (Cluster Friendly)", width: 768, height: 1024)
    ]
}

struct SelectOption: Identifiable, Codable, Hashable {
    var id: String
    let label: String
    let group: String
}

struct CharacterBankEntry: Codable {
    let label: String
    let base: String
    let anime: String
    let furry: String
    let canonical_outfit: String
}

struct CatalogBundle: Codable {
    let subjects: [SelectOption]
    let anatomies: [SelectOption]
    let outfits: [SelectOption]
    let poses: [SelectOption]
    let duo_poses: [SelectOption]
    let settings: [SelectOption]
    let lightings: [SelectOption]
    let character_banks: [String: CharacterBankEntry]
    let anatomy_pos: [String: String]
    let anatomy_neg: [String: String]
}

struct VaultImageItem: Identifiable, Codable, Hashable {
    let id: String
    let filename: String
    let prompt: String
    let negativePrompt: String
    let modelName: String
    let engine: String
    let width: Int
    let height: Int
    let seed: Int
    let steps: Int
    let cfgScale: Double
    let createdAt: Date
    var remoteURL: String?
}

struct PromptVariantCard: Identifiable, Codable, Hashable {
    var id: String { title }
    let title: String
    let recommended_for: String
    let prompt: String
    let negative: String
}

