    static let shared: CatalogBundle = {
        guard let data = Data(base64Encoded: encodedCatalog, options: .ignoreUnknownCharacters),
              let decoded = try? JSONDecoder().decode(CatalogBundle.self, from: data) else {
            return CatalogBundle(
                subjects: [],
                anatomies: [],
                outfits: [],
                poses: [],
                duo_poses: [],
                settings: [],
                lightings: [],
                character_banks: [:],
                anatomy_pos: [:],
                anatomy_neg: [:]
            )
        }
        return decoded
    }()

    static let clusterModels: [String] = [
        "WAI-NSFW-illustrious-SDXL",
        "Pony Diffusion V6 XL",
        "AlbedoBase XL (SDXL)",
        "Juggernaut XL",
        "Realistic Vision",
        "Anything Diffusion"
    ]

    static let stylePresets: [(id: String, label: String)] = [
        ("qwen_anime", "Anime / Illustrious / Booru XL"),
        ("furry_anthro", "Anthro / Furry / Kemono XL"),
        ("qwen_photoreal", "Ultra Photorealistic 8K"),
